import{_ as i,J as o,b as r,e as s,a8 as p,f as a,L as m,q as n}from"./chunks/framework.CumEd6mW.js";const B=JSON.parse('{"title":"GR32.ImageFormats.BMP","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32.ImageFormats.BMP","entity":"GR32.ImageFormats.BMP","kind":"Unit","summary":"Provides bitmap image format adapter and reader support for standard BMP files.","seealso":["[[GR32.ImageFormats.TBitmap]]"],"title":"GR32.ImageFormats.BMP","date":1788957278000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32.ImageFormats/Image Formats/GR32.ImageFormats.BMP/index.md","filePath":"api/GR32.ImageFormats/Image Formats/GR32.ImageFormats.BMP/index.md","lastUpdated":1788957278000,"timestamp":1788957278000,"datetime":"2026-09-09T12:34:38.000Z"}'),l={name:"api/GR32.ImageFormats/Image Formats/GR32.ImageFormats.BMP/index.md"};function d(c,e,g,f,h,u){const t=o("ApiMembers");return r(),s("div",null,[e[0]||(e[0]=p('<p class="api-summary">Provides bitmap image format adapter and reader support for standard BMP files.</p><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32.ImageFormats.BMP</code> unit implements image format adapters and readers for standard Windows bitmap files (<code>.bmp</code>) using the native <a href="/api/GR32/TBitmap32/">TBitmap32</a> BMP support.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The native Graphics32 BMP implementation only supports writing BMP files in 32-bit ARGB format. By default using the V4 sub-format.</p><p>The default sub-format can be specified with the <code>DefaultBitmapHeaderVersion</code> global setting.</p></div><div class="warning custom-block"><p class="custom-block-title">BMP Version 5</p><p>Note that while Graphics32 fully support reading and writing the BMP V5 sub-format, most other applications and libraries either doesn&#39;t support this format, or claim to support it but has misinterpreted the specification.</p><p>In order to work around this problem, when copying a <code>TBitmap32</code> to the clipboard, if Graphics32&#39;s native PNG support is enabled (<code>TImageFormatAdapterPNG32</code>), then Graphics32 will additionally place a copy of the bitmap in PNG format onto the clipboard. Most applications will give precedence to the PNG format when copying from the clipboard.</p><p>See also:</p><ul><li><a href="https://github.com/graphics32/graphics32/issues/257" target="_blank" rel="noreferrer">Copy to clipboard, image got shifted - Graphics32, issue #257</a></li><li><a href="https://forums.paint.net/topic/122848-pasting-dibv5-image/" target="_blank" rel="noreferrer">Paint-NET - Pasting DIBv5 image</a></li><li><a href="https://forums.paint.net/topic/124628-1-px-line-on-top-of-every-image-pasted-into-firefox-from-paintnet/" target="_blank" rel="noreferrer">1 px line on top of every image pasted into Firefox from paint.net</a></li><li><a href="https://bugzilla.mozilla.org/show_bug.cgi?id=1866655" target="_blank" rel="noreferrer">Support “short” BI_BITFIELDS DIBv5 when pasting images (pixel data shifted when copy/pasting from Paint.NET) - Mozilla issue 1866655</a></li></ul></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>By design, the native Graphics32 BMP implementation does not support reading the legacy indexed (palette), or RLE compressed BMP formats. For these formats it falls back to reading the BMP using the standard <code>TBitmap</code> class (<a href="/api/GR32.ImageFormats/Image Formats/GR32.ImageFormats.TBitmap/">GR32.ImageFormats.TBitmap</a>).</p></div><hr>',7)),a("p",null,[m(t,{type:"members"})]),e[1]||(e[1]=a("h2",{id:"see-also",tabindex:"-1"},[n("See also "),a("a",{class:"header-anchor",href:"#see-also","aria-label":'Permalink to "See also"'},"​")],-1)),e[2]||(e[2]=a("ul",null,[a("li",null,[a("a",{href:"/api/GR32.ImageFormats/Image Formats/GR32.ImageFormats.TBitmap/"},"GR32.ImageFormats.TBitmap")])],-1))])}const I=i(l,[["render",d]]);export{B as __pageData,I as default};
